    const uint8_t* b_ = (const uint8_t*)p;
    return (uint32_t)(((((uint32_t)b_[0] << 0) | ((uint32_t)b_[1] << 8) | ((uint32_t)b_[2] << 16) | ((uint32_t)b_[3] << 24)) >> 0) & 0xFFFFFFFU);
